  | awk -F'|' '{
      gsub(/ /, "", $5);
      if ($5 !~ /^[1-8]$/) print "Bad segment:", $0
    }'
Expected result:
# no output

Check vaccine type and lineage fields
grep "^&gt;" source/vaccines.fasta \
  | awk -F'|' '{
      type=$6; lineage=$7;
      gsub(/^ +| +$/, "", type);
      gsub(/^ +| +$/, "", lineage);
      if (type == "" || lineage == "") print "Missing type/lineage:", $0
    }'
